-- ProofMode 3.0 complete 60-template launch library.
-- Run after 003_entertainment_engine.sql.
on conflict (id) do update set
  title=excluded.title, promise=excluded.promise, category=excluded.category, difficulty=excluded.difficulty,
  duration_days=excluded.duration_days, proof_method=excluded.proof_method, rule=excluded.rule,
  example_caption=excluded.example_caption, cover_emoji=excluded.cover_emoji, safety_note=excluded.safety_note,
  is_featured=excluded.is_featured, sort_rank=excluded.sort_rank;
